import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.CvydjLy7.js";const p=JSON.parse('{"title":"案例工程一览","description":"","frontmatter":{"title":"案例工程一览"},"headers":[{"level":2,"title":"怎么组织","slug":"怎么组织","link":"#怎么组织","children":[]},{"level":2,"title":"工程约定","slug":"工程约定","link":"#工程约定","children":[]},{"level":2,"title":"业务规则落点","slug":"业务规则落点","link":"#业务规则落点","children":[]},{"level":2,"title":"测试规模","slug":"测试规模","link":"#测试规模","children":[]}],"relativePath":"project/index.md","filePath":"project/index.md","lastUpdated":1789497795000}'),c={name:"project/index.md"};function a(i,t,n,s,l,h){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="案例工程一览" tabindex="-1">案例工程一览 <a class="header-anchor" href="#案例工程一览" aria-label="Permalink to &quot;案例工程一览&quot;">​</a></h1><p>整套教程只讲一个业务：<strong>校园活动服务平台</strong>。它足够简单——场地、活动、报名三个概念；也足够真实——涉及分页检索、权限控制、名额控制、文件上传这类后端开发的高频场景。</p><table tabindex="0"><thead><tr><th>工程</th><th>技术要点</th><th>端口</th><th>首次出现</th></tr></thead><tbody><tr><td><code>activity-server</code></td><td>Spring Data JPA 版本，后端主线</td><td>8080</td><td><a href="/backend-engineering-course/ch01/">第 1 篇</a></td></tr><tr><td><code>activity-server-mybatisplus</code></td><td>等价实现的 MyBatis-Plus 版本，用于对照</td><td>8081</td><td><a href="/backend-engineering-course/ch06/">第 6 篇</a></td></tr><tr><td><code>activity-server-messaging</code></td><td>专题工程：Kafka、RabbitMQ、WebSocket/STOMP</td><td>—</td><td><a href="/backend-engineering-course/ch08/">第 8 篇</a></td></tr><tr><td><code>activity-server-testing</code></td><td>专题工程：四层测试与 Testcontainers</td><td>—</td><td><a href="/backend-engineering-course/ch09/">第 9 篇</a></td></tr><tr><td><code>activity-server-observability</code></td><td>专题工程：Actuator 端点、健康检查、指标</td><td>—</td><td><a href="/backend-engineering-course/ch10/">第 10 篇</a></td></tr><tr><td><code>activity-server-web</code></td><td>Vue 3 + Element Plus 管理端</td><td>5173</td><td>第 12 篇</td></tr></tbody></table><h2 id="怎么组织" tabindex="-1">怎么组织 <a class="header-anchor" href="#怎么组织" aria-label="Permalink to &quot;怎么组织&quot;">​</a></h2><p><code>activity-server</code> 与 <code>activity-server-mybatisplus</code> 是同一业务的两套实现，用于对照两种数据访问方式的写法差异。</p><p>第 8、9、10 篇各有一个专题工程。它们只保留最小一套分层代码，把篇幅留给当篇主题，互不依赖，可以单独运行与测试。这样安排是因为主线工程的测试要保持“零外部依赖”——需要 broker、需要 Docker 的代码不适合塞进去。</p><p>第 11 篇不新增工程，直接对主线工程 <code>activity-server</code> 做打包与容器化。工程根目录下的四个 <code>Dockerfile</code> 分别是分层、单层、CDS 三种写法，外加一个 <code>chown</code> 位置的反例，<code>.dockerignore</code> 配合它们使用；<code>pom.xml</code> 里额外声明了 <code>native-maven-plugin</code>，用于 GraalVM 原生镜像构建。</p><h2 id="工程约定" tabindex="-1">工程约定 <a class="header-anchor" href="#工程约定" aria-label="Permalink to &quot;工程约定&quot;">​</a></h2><p>六个工程共用同一套约定，读代码时按这个约定找位置：</p><table tabindex="0"><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td>根包</td><td><code>com.example.activity</code></td></tr><tr><td>分层</td><td><code>web</code> / <code>service</code> / <code>repository</code> / <code>domain</code> / <code>dto</code> / <code>common</code> / <code>config</code></td></tr><tr><td>统一响应</td><td><code>ApiResponse&lt;T&gt;</code>，<code>code = 0</code> 表示成功</td></tr><tr><td>分页</td><td>自定义 <code>PageResult&lt;T&gt;</code>，<code>page</code> 从 1 开始</td></tr><tr><td>JPA 配置</td><td>始终配 <code>spring.jpa.open-in-view: false</code></td></tr><tr><td>时间格式</td><td>接口统一 <code>yyyy-MM-dd HH:mm:ss</code></td></tr></tbody></table><p>分层依据与包结构的更多说明见<a href="/backend-engineering-course/ch02/">第 2 篇</a>。</p><h2 id="业务规则落点" tabindex="-1">业务规则落点 <a class="header-anchor" href="#业务规则落点" aria-label="Permalink to &quot;业务规则落点&quot;">​</a></h2><p>这套业务里有几条规则值得单独记住，后面各篇会反复用到：</p><table tabindex="0"><thead><tr><th>规则</th><th>落点</th></tr></thead><tbody><tr><td>只有审核通过的报名占名额</td><td><code>SignupService.approve</code>，名额满时返回 2005</td></tr><tr><td>下架是独立标记，不是状态</td><td><code>Activity.offShelf</code> 与 <code>ActivityStatus</code> 两个字段分开</td></tr><tr><td>同一场地同一时段不能有两个场次</td><td><code>[start, end)</code> 半开区间判重叠，边界相接不算冲突</td></tr><tr><td>报名截止后不能再报名</td><td><code>Activity.acceptsSignup</code>，实体里判，不由 Controller 判</td></tr></tbody></table><h2 id="测试规模" tabindex="-1">测试规模 <a class="header-anchor" href="#测试规模" aria-label="Permalink to &quot;测试规模&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工程</th><th>测试数</th><th>说明</th></tr></thead><tbody><tr><td><code>activity-server</code></td><td>84</td><td>单元测试、Web 切片、JPA 切片、整体启动</td></tr><tr><td><code>activity-server-mybatisplus</code></td><td>13</td><td>逻辑删除、自动填充、条件构造器与原子自增</td></tr><tr><td><code>activity-server-messaging</code></td><td>7</td><td>三条消息链路的测试手法</td></tr><tr><td><code>activity-server-testing</code></td><td>31</td><td>四层测试与 Testcontainers</td></tr><tr><td><code>activity-server-observability</code></td><td>22</td><td>端点、健康检查、指标</td></tr></tbody></table><p>这些数字是各篇写作过程中实际跑出来的，测试策略与耗时对照见<a href="/backend-engineering-course/ch09/">第 9 篇</a>。</p>',17)])])}const v=e(c,[["render",a]]);export{p as __pageData,v as default};
